def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == 4 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 4 for r in range(h))]

    def segments(size, separators):
        out = []
        start = 0
        for s in separators:
            if start < s:
                out.append((start, s))
            start = s + 1
        if start < size:
            out.append((start, size))
        return out

    rs = segments(h, sep_rows)
    cs = segments(w, sep_cols)
    panels = []
    for r0, r1 in rs:
        for c0, c1 in cs:
            panel = [row[c0:c1] for row in grid[r0:r1]]
            panels.append((r0, r1, c0, c1, panel))

    background = max(
        (grid[r][c] for r in range(h) for c in range(w)
         if r not in sep_rows and c not in sep_cols),
        key=lambda x: sum(
            1 for rr in range(h) for cc in range(w)
            if rr not in sep_rows and cc not in sep_cols and grid[rr][cc] == x
        )
    )

    sources = [p for p in panels if any(v != background for row in p[4] for v in row)]
    if not sources:
        return grid
    source = max(sources, key=lambda p: sum(v != background for row in p[4] for v in row))
    pattern = source[4]

    out = [row[:] for row in grid]
    for r0, r1, c0, c1, panel in panels:
        if (r1 - r0, c1 - c0) != (len(pattern), len(pattern[0])):
            continue
        if any(v != background for row in panel for v in row):
            continue
        for i in range(r1 - r0):
            for j in range(c1 - c0):
                out[r0 + i][c0 + j] = pattern[i][j]
    return out
